package cn.zhuatech.meetingai.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class MeetingMinutesPublicationServiceTest{private final MeetingMinutesPublicationService s=new MeetingMinutesPublicationService();@Test void publishesApprovedMinutes(){var r=s.assess(new MeetingMinutesPublicationService.Request("M1",true,true,true,true,true,true,true,0,true,true,true));assertThat(r.decision()).isEqualTo(MeetingMinutesPublicationService.Decision.PUBLISH);}@Test void reviewsRetentionAndAudit(){var r=s.assess(new MeetingMinutesPublicationService.Request("M2",true,true,true,true,true,true,true,0,false,false,true));assertThat(r.actions()).hasSize(2);}@Test void blocksUnsafeMinutes(){var r=s.assess(new MeetingMinutesPublicationService.Request("M3",false,false,false,false,false,false,false,2,true,true,false));assertThat(r.blockers()).hasSize(9);}}
